def main():
    root = ROOT / "example"
    catalogue = json.loads((root / "catalog.json").read_text(encoding="utf-8-sig"))
    ids = {entry["id"] for entry in catalogue}
    for identifier, title, components, data, procedure, expected, limits in EXAMPLES:
        folder = root / identifier
        folder.mkdir(exist_ok=True)
        (folder / "README.md").write_text(
            f"# {identifier[:2]} · {title}\n\n"
            f"[Apri la definizione GHX]({identifier}.ghx) · [Report eseguito](validation.json) · [Guida completa](../../docs/BRIDGE-DESIGN.md)\n\n"
            f"## Dati e componenti\n\n{data}\n\n`{components}`\n\n"
            f"## Procedura\n\nAprire il file con la Release corrente di BridGHe in Rhino 8. Gli input numerici sono in mm e le proprietà FEM in N-mm-MPa. "
            f"I parametri tipizzati memorizzati sono sostituibili collegando i normali componenti di proprietà/definizione.\n\n{procedure}\n\n"
            f"## Controlli attesi\n\n{expected}\n\n"
            f"## Ambito\n\n{limits}\n\n"
            "Il generatore risolve il documento, lo salva, lo riapre e ripete i controlli. `validation.json` riporta il risultato effettivo; `solverInvoked=false` significa che Straus non è stato eseguito.\n",
            encoding="utf-8")
        if identifier not in ids:
            catalogue.append(dict(number=int(identifier[:2]), id=identifier, title=title, group="Progettazione del modello",
                                  readme=f"{identifier}/README.md", definition=f"{identifier}/{identifier}.ghx", calculations=f"{identifier}/calcoli"))
    (root / "catalog.json").write_text(json.dumps(catalogue, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    index = root / "README.md"
    text = index.read_text(encoding="utf-8")
    marker = "## Progettazione del modello 33–45"
    text = text.split(marker)[0].rstrip()
    text += "\n\n" + marker + "\n\n" + "\n".join(f"- [{i[:2]} · {title}]({i}/README.md)" for i, title, *_ in EXAMPLES)
    text += "\n\nTredici definizioni GHX con soluzione e riapertura verificate senza solutore. [Procedura e limiti](../docs/BRIDGE-DESIGN.md).\n"
    index.write_text(text, encoding="utf-8")
    print("Documented 13 examples, 33–45.")

if __name__ == "__main__":
    main()
